var ck='';
try{ck=String(java.getCookie('https://www.shenwen.org')||'');}catch(e){}
var parts=ck.split(';');
var keep=[];
for(var i=0;i<parts.length;i++){
  var p=String(parts[i]).trim();
  if(p.length===0){continue;}
  if(p.indexOf('user_id')===0){keep.push(p);}
  else if(p.indexOf('user_name')===0){keep.push(p);}
  else if(p.indexOf('320cae9b112ceefc02d1f1bf69093c11')===0){keep.push(p);}
}
